/**
 * street-trees.js — the 1904 Prairie Avenue district's parkway elms (T-2473).
 *
 * WHAT IT DRAWS, from `data/street_trees/<scene>.json` (generated by
 * tools/plant_prairie_1904_street_trees.py from the parkway bands of the T-0474
 * grid): one file of elms in the grass strip between the walk and the curb on
 * every block face, about thirty feet apart, as the 1887-91 west-walk photograph
 * at 18th Street shows them (docs/RESEARCH/prairie_1904_street_trees.md). Every
 * position is reconstructed (docs/LIBERTIES.md L-prairie-parkway-elms-2473); the
 * species is inferred from the prints.
 *
 * HOW. With the grown American elm the 1835 timber draws (tree-model.js, T-2743)
 * — the owner asked for the 1835 flora as the base, and a second tree builder
 * would drift from the first — at the height a planted street elm grows to. A
 * few crowns are grown once and INSTANCED (tree-instances.js: each tree turned
 * and scaled on its own spot, at three levels by distance, culled per tree in
 * the view and the sun, every one in the sun's box casting, T-2948), because a
 * street file of planted elms is a few hundred trees of one age and a merged
 * buffer of four hundred unique crowns costs a phone tens of megabytes for no
 * difference anyone can see at a walk.
 *
 * THE TREES SETTING (owner, 2026-10-13: "be able to hide trees or make them
 * spring trees barely blooming so you can see the house"; then "an option to make
 * them spring trees, winter bare trees or make them all disappear"): `summer`, the
 * July canopy the scene date has and the default; `spring`, the same trees just
 * leafing, a few pale tufts on bare limbs, so the fronts read through them;
 * `winter`, the same limbs bare, the grown twigs with no leaf; and
 * `hidden`. A viewing choice, never a second claim about July 1904.
 *
 * A scene that does not list `street_trees` hands this no data base and it draws
 * nothing; a failed fetch draws nothing and records a problem.
 */

import * as THREE from 'three';
import { SPECIES } from './trees.js';
import { TREE_ALPHA_CUTOFF, patchTreeWind } from './tree-surface.js';
import { TreeInstances, createGrownTreeMaterials } from './tree-instances.js';
import { resolveBases } from './scene-loader.js';

export const STREET_TREE_MODES = ['summer', 'spring', 'fall', 'winter', 'hidden'];
const PARKWAY_LIFT_M = 0.05;      // street-grid.js CLASSES.parkway.lift
const CONF = { attested: 0, inferred: 0.5, reconstructed: 1 };
/**
 * The parkway elm: the 1835 record's colours and leaf, a street tree's shape.
 * Open-grown on a 14-ft sidewalk space it carries a clear bole to about a third
 * of its height and a high crown that arches over the walk (the photograph);
 * 17-23 m and 0.45-0.70 m at breast height for trees the 1887-91 print already
 * shows tall, a dozen years on. T-3017: grown on the open-grown elm's own habit
 * (tree-model.js ARCH.ulmus_americana_vase: the forked bole, the arching limbs,
 * the hanging sprays), as wide as about 0.85 of its height, so the two files'
 * crowns meet over the roadway as they do in the owner's photographs.
 */
function elmSpec(mode) {
  const base = SPECIES.ulmus_americana;
  const spec = {
    ...base, speciesId: 'ulmus_americana', arch: 'ulmus_americana_vase', conf: CONF.reconstructed, crownW: null,
    form: 'gallery', h: [17, 23], dbh: [0.45, 0.70], spreadK: 0.85, boleK: 0.48, puffs: 8, lean: 0.05,
  };
  if (mode === 'spring') {
    // Just leafing: the limbs of a summer tree carry small pale tufts. More
    // masses means more limbs to see; each is a fraction of a summer mass.
    return { ...spec, puffs: 13, puffScale: 0.40, dark: 0x6d7a35, light: 0xc3cf7a };
  }
  if (mode === 'fall') {
    // T-2481: the American elm turns a clear yellow in October and drops early,
    // so the crown is thinner than July's and the limbs show through it.
    return { ...spec, puffScale: 0.82, dark: 0x9a7420, light: 0xe8c45a };
  }
  if (mode === 'winter') {
    // Bare: the summer crown's sprays, drawn from the twig atlas in the grey
    // brown of elm wood (the twig ink is about 0.44 grey, so these are lifted).
    return { ...spec, dark: 0x8c8474, light: 0xb8b0a0 };
  }
  return spec;
}

async function getJSON(url) {
  const res = await fetch(url, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} — ${url}`);
  return res.json();
}

/**
 * T-2743: the parkway's level rings, tighter than the timber's (tree-instances.js
 * LEVELS). A parkway is a file of tall crowns every nine metres down every street
 * in view, so the timber's 42 m near ring holds a dozen full elms here; the
 * spawn's elms were 466k triangles on those rings against the 92k the old crowns
 * drew. Near is the elm a visitor stands under, mid the next few down the walk.
 * T-3017: the phone's `distant` comes in at 220 m (300 before): the grown elm's
 * distant level keeps its forked stems under its crown, and at 220 m an elm is
 * about 70 px tall on a 390-px phone, below what its far sprays resolve.
 */
const STREET_LEVELS = {
  full: { near: 10, mid: 44, distant: 420 },
  balanced: { near: 10, mid: 40, distant: 380 },
  light: { near: 0, mid: 32, distant: 220 },
};
/**
 * T-2833 — THE CONTEXT CITY'S TREES. The faded city around the district
 * (context.js) hands its trees here, and they are drawn as these same grown elms,
 * sharing their crowns, their setting and their season: the owner asked for real
 * trees at the street ends in place of the old blob crowns. A background tree takes
 * its levels as if it stood CONTEXT_LOD_K times further off, so past ~280 m it is
 * the `distant` level (46 triangles, about what the blob and its trunk cost) and
 * only the nearest few are a parkway elm's full crown.
 */
const CONTEXT_LOD_K = 1.5;
/** The parkway elm's middle height: a background tree's own height scales it. */
const ELM_MID_H = 20;
/**
 * T-2948 — EVERY ELM IN THE SUN'S BOX CASTS, and a level change dissolves.
 * T-2743 let only the elms within 32 m cast, and the owner walking south down
 * Prairie (2026-10-20) saw the street's shade stop 32 m ahead and pop in as he
 * came on; past it the far set now casts too, with its coarse crowns, out to the
 * sun's own box (world.js SHADOW_REACH_M). The fine set's edge is put on the mid
 * ring's, so a stem changes set and level in one step, and every step is a
 * FADE_S dissolve (tree-instances.js) rather than the frame where a crown's
 * leaves popped in.
 */
const FADE_S = 0.8;

/** T-2743: the Season setting's crowns, as the grown elm's leaf cover. Spring is
 *  just leafing (a few small pale tufts), fall a thinner yellow crown, winter bare
 *  limbs and twigs with no leaf card at all. */
const SEASON = {
  summer: {},
  spring: { leafCover: 0.55, leafScale: 0.45 },
  fall: { leafCover: 0.72, leafScale: 0.9 },
  winter: { leafCover: 0 },
};

function treeCard(t, doc) {
  const sp = doc.species ?? {};
  const pl = doc.placement ?? {};
  const young = t.kind === 'young';
  return {
    id: t.id,
    sidecar: {
      name: young ? 'A young parkway elm' : 'A parkway elm',
      phase: null,
      change_note: (young
        ? 'A young elm planted in a gap in the parkway file, as the 1901 photograph of 1700 Prairie shows one. '
        : 'One of the elms in the grass parkway between the walk and the curb. ')
        + 'The 1887-91 photograph from this walk at 18th Street shows a single file of tall elms; '
        + 'this tree\'s spot is our reconstruction.',
      placement: {
        symbolic_location: t.face,
        position_confidence: pl.tier ?? 'reconstructed',
        position_sources: [],
        position_note: pl.note ?? '',
      },
      attributes: {
        species: {
          value: sp.common ?? 'American elm', confidence: sp.tier ?? 'inferred',
          sources: sp.sources ?? [], note: sp.note ?? '',
        },
        position: {
          value: `${Math.round(t.e * 10) / 10} E, ${Math.round(t.n * 10) / 10} N`,
          confidence: pl.tier ?? 'reconstructed', sources: [],
          note: `About ${pl.spacing_ft ?? 30} ft from the next tree, nearer the curb than the walk. ${pl.liberty ?? ''}`.trim(),
        },
      },
      citations: [],
      research_doc: 'docs/RESEARCH/prairie_1904_street_trees.md',
      research_note: `Tree ${t.id} of data/street_trees/1904.json (T-2473). ${pl.liberty ?? ''}`.trim(),
    },
  };
}

/**
 * @param {object} o dataBase (data/ root, or null when the scene does not list
 *   the layer) · sceneId · terrain · confidence · problems · detail · lowSpec ·
 *   mode ('summer' | 'spring' | 'fall' | 'winter' | 'hidden') · checkpoint · levelAt (the
 *   street grid's drop below the field at a point: the parkway falls toward the curb, T-2474)
 */
export async function createStreetTrees({
  dataBase, sceneId, terrain, confidence = null, problems = [], detail = 'full',
  lowSpec = false, mode = 'summer', checkpoint = () => null, levelAt = null, contextTrees = null,
} = {}) {
  const group = new THREE.Group();
  group.name = 'street-trees';
  const stats = { trees: 0, young: 0, triangles: 0, drawCalls: 0, mode, detail, crowns: 0, context: 0 };
  const out = {
    group, stats, records: [],
    pickAt: () => null, update() {}, setMode: async () => {}, setDetail: async () => {}, dispose() {},
  };
  if (!dataBase || !terrain) return out;
  let doc;
  try {
    doc = await getJSON(new URL(`street_trees/${sceneId}.json`, dataBase));
  } catch (err) {
    problems.push(`street trees: ${err.message} — no parkway tree is drawn`);
    return out;
  }
  const trees = doc.trees ?? [];
  out.records = trees;
  stats.trees = trees.length;
  stats.young = trees.filter((t) => t.kind === 'young').length;
  const variants = Math.max(1, doc.placement?.variants ?? 12);

  /* ---- the material: the grown trees' own, so the two read as one wood --- */
  // T-2743: the elms are the American elm the 1835 timber grows from
  // tree-model.js, at the parkway tree's height, drawn by tree-instances.js with
  // its levels and shadow ring. The leaf and bark atlases load once; a Season or
  // detail change re-grows the crowns, not the textures.
  const uWind = { value: 0 };
  const mats = await createGrownTreeMaterials({
    assetBase: resolveBases().assetBase, uWind, confidence, patchWind: patchTreeWind,
    lowSpec: lowSpec || detail === 'light', alphaCutoff: TREE_ALPHA_CUTOFF, problems, fade: true,
  });
  // T-3223: the front yards' shrubs and lawn trees grow on these same atlases.
  out.materials = mats;

  /* ---- where each tree stands ------------------------------------------- */
  const placed = trees.map((t) => {
    const y = terrain.surfaceHeight(t.e, t.n) + (levelAt?.(t.e, t.n) ?? 0) + PARKWAY_LIFT_M;
    return { t, y, variant: t.variant ?? 0, h: 20 };
  });

  let forest = null;
  let current = { mode: null, detail: null };
  const build = async (wantMode, wantDetail) => {
    if (forest) { group.remove(forest.group); forest.dispose(); forest = null; }
    stats.mode = wantMode; stats.detail = wantDetail; stats.triangles = 0; stats.drawCalls = 0;
    current = { mode: wantMode, detail: wantDetail };
    group.visible = wantMode !== 'hidden';
    if (wantMode === 'hidden' || !placed.length) return;
    // Three elms, grown once, stand for all four hundred: a young tree is one of
    // them at its record's smaller scale. Each variant is a megabyte and more of
    // geometry, and a parkway of one age is the case where siblings read true.
    const spec = elmSpec(wantMode);
    const rings = STREET_LEVELS[wantDetail] ?? STREET_LEVELS.full;
    const grown = new TreeInstances({ level: wantDetail, shadowM: rings.mid, name: 'street-trees',
      variants: () => Math.min(variants, 3), levels: STREET_LEVELS, fadeS: FADE_S, castFar: true });
    for (const p of placed) {
      const sc = p.t.scale ?? 1;
      p.h = grown.add(spec, p.t.e, p.y, -p.t.n, sc,
        { yaw: (p.t.yaw_deg ?? 0) * Math.PI / 180, variant: p.variant });
    }
    const background = contextTrees?.(wantDetail) ?? [];
    for (const t of background) {
      grown.add(spec, t.e, t.y + (levelAt?.(t.e, t.n) ?? 0), -t.n, t.h / ELM_MID_H, { lodK: CONTEXT_LOD_K });
    }
    stats.context = background.length;
    const pause = checkpoint(); if (pause) await pause;
    forest = await grown.build({ ...mats, checkpoint, season: SEASON[wantMode] ?? {} });
    group.add(forest.group);
    stats.drawCalls = forest.stats.drawCalls;
    stats.crowns = forest.stats.variants;
    stats.grown = forest.stats;
  };
  await build(STREET_TREE_MODES.includes(mode) ? mode : 'summer', detail);

  let wind = 0;
  out.update = (dt, camera = null) => {
    wind += dt || 0; uWind.value = wind;
    if (camera && forest) {
      forest.update(camera.position, dt || 0);
      stats.triangles = forest.stats.triangles;
    }
  };
  /** Finish every dissolve at once (a still frame for a reading or a shot). */
  out.settle = () => { forest?.settle(); };
  out.setMode = async (m) => {
    if (!STREET_TREE_MODES.includes(m) || m === current.mode) return;
    await build(m, current.detail);
  };
  out.setDetail = async (d) => {
    if (d === current.detail) return;
    await build(current.mode, d);
  };

  /** A trunk under the crosshair: a vertical cylinder for the bole, up to the
   *  crown. Only the bole, so a click through the leaves at a house front still
   *  opens the house. */
  const ray = new THREE.Raycaster();
  out.pickAt = (ndc, camera) => {
    if (!camera || !forest || !group.visible) return null;
    ray.setFromCamera(ndc ?? new THREE.Vector2(0, 0), camera);
    const o = ray.ray.origin; const d = ray.ray.direction;
    const a = d.x * d.x + d.z * d.z;
    if (a < 1e-9) return null;
    let best = null;
    for (const p of placed) {
      const s = p.t.scale ?? 1;
      const h = p.h;
      const dx = o.x - p.t.e; const dz = o.z + p.t.n;
      const tt = -(dx * d.x + dz * d.z) / a;
      if (!(tt > 0 && tt < 200)) continue;
      const px = dx + d.x * tt; const pz = dz + d.z * tt;
      const yy = o.y + d.y * tt;
      const r = 0.45 * s;
      if (px * px + pz * pz < r * r && yy > p.y - 0.2 && yy < p.y + h * 0.5
        && (!best || tt < best.distance)) {
        best = { p, distance: tt, point: new THREE.Vector3(o.x + d.x * tt, yy, o.z + d.z * tt) };
      }
    }
    if (!best) return null;
    const record = treeCard(best.p.t, doc);
    return { id: record.id, record, point: best.point, distance: best.distance };
  };
  out.cardFor = (id) => {
    const t = trees.find((x) => x.id === id);
    return t ? treeCard(t, doc) : null;
  };
  out.dispose = () => {
    if (forest) { group.remove(forest.group); forest.dispose(); }
    mats.dispose();
  };
  return out;
}
